#!/usr/bin/env python3
import json, base64, urllib.request

WF_ID = "eU4PGTpWCBAOOPZp"
API_KEY = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiIxM2YzOTNjYi0yMTMxLTQwN2ItOWNlNS0xMDVkOWI4OTE5MDYiLCJpc3MiOiJuOG4iLCJhdWQiOiJwdWJsaWMtYXBpIiwianRpIjoiZDllZTgzNjItOTg3MS00NDIyLWEzMTMtMmI5YjA0MWQxY2JkIiwiaWF0IjoxNzc4ODQyMzE3fQ.gdUhqHCEQVlw-gJcNWi8VXmgxpwp3uIwwJUFBbsYhs4"

# Workflow data (base64 encoded)
DATA_B64 = ""

# Decode workflow
wf_data = json.loads(base64.b64decode(DATA_B64).decode("utf-8"))

# Remove fields that the API doesn't accept on PUT
for key in ["id", "createdAt", "updatedAt", "versionId"]:
    wf_data.pop(key, None)

payload = json.dumps(wf_data).encode("utf-8")

url = f"http://localhost:5678/api/v1/workflows/{WF_ID}"
print(f"Enviando PUT para {url} ...")

req = urllib.request.Request(
    url,
    data=payload,
    headers={
        "X-N8N-API-KEY": API_KEY,
        "Content-Type": "application/json"
    },
    method="PUT"
)

try:
    with urllib.request.urlopen(req, timeout=30) as resp:
        body = resp.read().decode("utf-8")
        result = json.loads(body)
        print(f"✅ Sucesso! Status: {resp.status}")
        print(f"   Workflow: {result.get('name')} (ID: {result.get('id')})")
        print(f"   Nodes: {len(result.get('nodes', []))}")
except urllib.error.HTTPError as e:
    body = e.read().decode("utf-8")
    print(f"❌ Erro HTTP {e.code}: {body[:500]}")
except Exception as ex:
    print(f"❌ Erro: {ex}")
